(()=>{'use strict';const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let topic='inspect',busy=false;const box=document.createElement('section');box.className='findings-ace';box.id='findingsAce';
function render(){const c=window.AceEvidenceCards.get(topic);box.innerHTML=`<div class="host-heading"><div class="ace-portrait"><img src="assets/ace-host.svg" alt="Ace, casino host in a suit and glasses" width="88" height="106"></div><div><span class="findings-number">ACE · POWERED BY GEMINI</span><h2>A short answer. A checkable source.</h2><p>${window.GILDED_HOST_ENDPOINT?'Ask a question. Get a second perspective.':'Offline guide'}</p></div></div><div class="findings-actions" role="group" aria-label="Choose an evidence question">${[['inspect','Why inspect?'],['location','Did moving help?'],['model','Why trust the model?'],['downtime','Lost play?'],['guests','Player results?'],['loyalty','Loyalty costs?'],['budget','Why this budget?']].map(([id,label])=>`<button data-ace-topic="${id}" aria-pressed="${id===topic}">${label}</button>`).join('')}</div><h3>${esc(c.title)}</h3><p>${esc(c.answer)}</p><details><summary>Challenge this answer</summary><p>${esc(c.challenge)}</p></details><details><summary>What would we check next?</summary><p>${esc(c.measure)}</p></details><p class="ace-source">${esc(c.source)} <a href="${c.href}">Read the source ↗</a></p><button class="outline" data-desk="${c.desk}">Open the supporting analysis →</button><button type="button" class="outline" data-ace-challenge>What would prove us wrong?</button><form id="findingsAsk"><label for="findingsQuestion">Ask a follow-up</label><div><input id="findingsQuestion" maxlength="400" placeholder="What would change this recommendation?" ${window.GILDED_HOST_ENDPOINT?'':'disabled'}><button ${!window.GILDED_HOST_ENDPOINT||busy?'disabled':''}>${busy?'Checking…':'Ask Ace'}</button></div><small>${window.GILDED_HOST_ENDPOINT?'Answers draw on the reviewed findings above.':'Live follow-up chat needs server activation. The explanations above work without AI.'}</small></form><div id="findingsReply" role="status" aria-live="polite"></div>`;}
box.addEventListener('click',e=>{if(e.target.closest('[data-ace-challenge]')&&!busy){$('findingsQuestion').value='Challenge this finding. What is the strongest alternative explanation, what would change our decision, and how could we test it?';box.querySelector('form').requestSubmit();return;}const b=e.target.closest('[data-ace-topic]');if(b&&!busy){topic=b.dataset.aceTopic;render();}});
box.addEventListener('submit',async e=>{e.preventDefault();if(busy||!window.GILDED_HOST_ENDPOINT)return;const message=$('findingsQuestion').value.trim();if(!message)return;busy=true;render();try{const r=await fetch(window.GILDED_HOST_ENDPOINT,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mode:'findings',topic,detail:'simple',message,state:window.AceSimCore.fresh()}),signal:AbortSignal.timeout(50000)});if(!r.ok)throw Error();const data=await r.json();if(typeof data.reply!=='string')throw Error();$('findingsReply').textContent='Gemini: '+data.reply;const refs=(data.evidenceUsed||[]).filter(r=>window.AceEvidenceCards.topics.includes(r.topic));if(refs.length){const trace=document.createElement('details');const title=document.createElement('summary');title.textContent='Evidence Ace checked ('+refs.length+')';trace.append(title);for(const r of refs){const c=window.AceEvidenceCards.get(r.topic);const item=document.createElement('p'),link=document.createElement('a');link.href=c.href;link.textContent=c.title+' — '+c.source;item.append(link);trace.append(item);}$('findingsReply').append(trace);}}catch{$('findingsReply').textContent='Live AI is unavailable. The reviewed answer and source above remain available.';}finally{busy=false;box.querySelector('form button').disabled=false;box.querySelector('form button').textContent='Ask Ace';}});
const shell=document.createElement('details');shell.className='findings-ace-shell';const summary=document.createElement('summary');summary.textContent='Ask Ace to explain or challenge a finding';shell.append(summary,box);$('findingsOverview').querySelector('.findings-check').before(shell);render();
})();
